import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.DrWxItG4.js";const u=JSON.parse('{"title":"Dialog elements","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dialog-elements.md","filePath":"guide/dialog-elements.md"}'),c={name:"guide/dialog-elements.md"};function n(i,t,s,l,r,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="dialog-elements" tabindex="-1">Dialog elements <a class="header-anchor" href="#dialog-elements" aria-label="Permalink to &quot;Dialog elements&quot;">​</a></h1><p>This page lists every element the 5.60 client&#39;s dialog parser (<code>0x16b7560</code>) understands, in the order it checks them. <a href="/gtps-guide/functions/OnDialogRequest">OnDialogRequest</a> passes its text to that parser. It also describes what the client sends back in <code>action|dialog_return</code>. Everything here comes from the decompiled client. Where a field&#39;s meaning is a guess from how the value is used, the table says &quot;probably&quot;.</p><h2 id="how-the-text-is-read" tabindex="-1">How the text is read <a class="header-anchor" href="#how-the-text-is-read" aria-label="Permalink to &quot;How the text is read&quot;">​</a></h2><ul><li>The text is split into lines at <code>\\n</code>, and each line into fields at <code>|</code>. Field 0 is the element name. The tables below number the fields from 1.</li><li>An unknown element name is skipped silently.</li><li>An element with too few fields logs <code>Error with &lt;element&gt; parms</code> and is skipped. &quot;Min&quot; in the tables is the smallest number of fields, counting the name, that the parser accepts.</li><li>Text fields get the color from <code>set_default_color</code> put in front of them, and <code>&lt;CR&gt;</code> in them becomes a line break.</li><li>Size fields compare exactly against <code>big</code>; anything else is small. Alignment fields compare exactly against <code>center</code>; anything else, <code>left</code> and <code>right</code> included, is left-aligned.</li><li>Most elements take one more optional field at the end, written <strong>opts</strong> below. It is a list of <code>key:value</code> pairs separated by <code>;</code>. When it has <code>featureEnableFlag:&lt;n&gt;</code>, the element is only added if feature <code>n</code> is on (the flags come from <a href="/gtps-guide/functions/OnSetFeatureEnableFlags">OnSetFeatureEnableFlags</a>). Some builders read other keys from the same list: the label builder reads <code>additionalPosX</code>, <code>additionalPosY</code>, <code>frameSize</code> and <code>iconFrame</code>.</li></ul><h2 id="elements-checked-by-length-first" tabindex="-1">Elements checked by length first <a class="header-anchor" href="#elements-checked-by-length-first" aria-label="Permalink to &quot;Elements checked by length first&quot;">​</a></h2><p>The parser first compares a few names by their length and raw bytes, before the general list.</p><table tabindex="0"><thead><tr><th>Element</th><th>Min</th><th>Fields</th><th>Notes</th></tr></thead><tbody><tr><td><code>add_rating_item</code></td><td>3</td><td>name, settings</td><td>A star-rating row. The settings are <code>key:value;…</code>, with keys <code>maxRating</code>, <code>defaultRating</code>, <code>selectedIcons</code>, <code>unSelectedIcons</code>, <code>touchPadding</code> and <code>alignment</code>. Sends back <code>rating_item|&lt;name&gt;|&lt;value&gt;</code>. Its error message calls it <code>add_rating_control</code>.</td></tr><tr><td><code>add_image</code></td><td>4</td><td>file, a, b, [scale], [opts]</td><td>An image (<code>dialogImage</code>). a and b are floats, probably the size. scale defaults to 1.0.</td></tr><tr><td><code>add_label</code></td><td>4</td><td>size, text, align, (unused), [opts]</td><td>A text line.</td></tr><tr><td><code>add_inline_label</code></td><td>4</td><td>size, text, align, int, [opts]</td><td>Probably a label that stays on the current row, with an icon (the int).</td></tr><tr><td><code>add_label_with_icon</code></td><td>5</td><td>size, text, align, item id, [opts]</td><td>A label with an item icon on the left.</td></tr><tr><td><code>add_label_with_counter</code></td><td>4</td><td>size, text, align, input name, [opts]</td><td>A label that counts the characters in the text input named by field 4 (builder <code>0x1699aa8</code> reads <code>inputName</code>).</td></tr><tr><td><code>add_seed_color_icons</code></td><td>2</td><td>int, [opts]</td><td>Probably the color icons for the seed with that item id.</td></tr><tr><td><code>add_dual_layer_icon_label</code></td><td>8</td><td>size, text, align, icon 1, icon 2, float, float, [opts]</td><td>Two icons drawn on top of each other. A non-zero 7th field turns on an option.</td></tr><tr><td><code>add_searchable_item_list</code></td><td>3</td><td>name, items, …</td><td>A list with a search box (<code>SearchableListEntity</code>). Clicking an entry sends <code>buttonClicked|searchableItemListButton_…</code>.</td></tr></tbody></table><h2 id="labels-text-and-progress" tabindex="-1">Labels, text and progress <a class="header-anchor" href="#labels-text-and-progress" aria-label="Permalink to &quot;Labels, text and progress&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Min</th><th>Fields</th><th>Notes</th></tr></thead><tbody><tr><td><code>add_label_with_icon_button</code></td><td>6</td><td>size, text, align, item id, string (probably the button name), [flags, default <code>noflags</code>], [string], [opts]</td><td>A clickable label.</td></tr><tr><td><code>add_label_with_icon_button_list</code></td><td>7</td><td>size, text, align, list 1, list 2, list 3, …</td><td>A list of priced entries (builder <code>0x16b3530</code>), shown with &quot;Cost: … World Lock(s)&quot; and &quot;(Quantity: …)&quot;. The lists are comma-separated item ids (<code>itemID_transID</code>, <code>itemID_iconID</code>).</td></tr><tr><td><code>add_label_with_ele_icon</code></td><td>6</td><td>size, text, align, item id, int, [opts]</td><td>A label with an icon. The 5th field probably picks the element.</td></tr><tr><td><code>add_achieve</code></td><td>5</td><td>title, text, align, achievement id, [opts]</td><td>An achievement row.</td></tr><tr><td><code>add_achieve_button</code></td><td>5</td><td>title, text, align, achievement id, [string], [opts]</td><td>The same row as a button.</td></tr><tr><td><code>add_achieve_custom</code>, <code>add_achieve_custom_btn</code></td><td>8</td><td>title, text, align, int, string, int, int, [opts]</td><td>Custom achievement row, plain or clickable.</td></tr><tr><td><code>add_player_info</code>, <code>add_player_info_small</code></td><td>5</td><td>name, level, current, max, [opts]</td><td>Shows &quot;Level N&quot; with &quot;(current/max)&quot; or &quot;(MAX!)&quot;.</td></tr><tr><td><code>add_fish_info</code></td><td>5</td><td>text, int, int, int, [opts]</td><td>The same layout, used for fish.</td></tr><tr><td><code>add_progress_bar</code></td><td>5</td><td>text, string, string, int, int, [string], [int], [opts]</td><td>A progress bar.</td></tr><tr><td><code>add_textured_progress_bar</code></td><td>13</td><td>text, int, int, string, int, int, layout, float, float, float, int, int, float, [background], [string]</td><td>A bar drawn from textures. The layout (field 7) is <code>fixed</code>, <code>relative</code>, <code>pre_icon</code> or <code>iconlist</code>. The background defaults to <code>barBG</code>.</td></tr><tr><td><code>add_textured_progress_bar_with_icon</code></td><td>15</td><td>as above, plus an icon</td><td>Same layout keywords as above.</td></tr><tr><td><code>add_textbox</code></td><td>3</td><td>text, align, [opts]</td><td>Wrapped text.</td></tr><tr><td><code>add_smalltext</code></td><td>3</td><td>text, align, [opts]</td><td>The same, in a smaller font.</td></tr><tr><td><code>add_custom_textbox</code></td><td>4</td><td>text, font size (float), align, [opts]</td><td></td></tr><tr><td><code>add_clock</code></td><td>4</td><td>text, size, align, [opts]</td><td></td></tr><tr><td><code>add_smalltext_forced</code>, <code>add_smalltext_forced_alpha</code></td><td>3</td><td>text, align, [opts] / two strings</td><td>One of the two takes text, align and opts; the other takes two plain strings and uses <code>TextBoxRender</code> with a <code>fontScale</code>. Which is which wasn&#39;t settled.</td></tr></tbody></table><h2 id="pickers" tabindex="-1">Pickers <a class="header-anchor" href="#pickers" aria-label="Permalink to &quot;Pickers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Min</th><th>Fields</th><th>What happens</th></tr></thead><tbody><tr><td><code>add_player_picker</code></td><td>3</td><td>name, label, [opts]</td><td>Opens a &quot;Select a player&quot; menu. The choice is sent at once, as <code>&lt;name&gt;|&lt;int&gt;</code> (probably the player&#39;s netID), in the <code>dialog_return</code>.</td></tr><tr><td><code>add_item_picker</code></td><td>4</td><td>name, label, text, [opts]</td><td>Opens the item picker. Picking an item sends <code>dialog_return</code> at once with <code>&lt;name&gt;|&lt;item id&gt;</code>.</td></tr><tr><td><code>add_confirm_item_picker</code></td><td>5</td><td>name, label, text, confirm text, [opts]</td><td>The same, with a confirmation step (<code>ConfirmMsg</code>).</td></tr></tbody></table><h2 id="buttons" tabindex="-1">Buttons <a class="header-anchor" href="#buttons" aria-label="Permalink to &quot;Buttons&quot;">​</a></h2><p>Buttons are named <code>_button_&lt;name&gt;</code>. Clicking one closes the dialog and sends <code>dialog_return</code> with <code>buttonClicked|&lt;name&gt;</code>.</p><table tabindex="0"><thead><tr><th>Element</th><th>Min</th><th>Fields</th><th>Notes</th></tr></thead><tbody><tr><td><code>text_scaling_string</code></td><td>2</td><td>text</td><td>Sets the sample text that button widths are scaled to (probably).</td></tr><tr><td><code>add_community_button</code></td><td>4</td><td>name, label, string, [opts]</td><td></td></tr><tr><td><code>add_button</code></td><td>4</td><td>name, label, flags, (unused), (unused), [notify], [opts]</td><td>The plain button. If <code>flags</code> contains <code>off</code>, the button is drawn at 30% alpha and probably can&#39;t be clicked. A non-zero <code>notify</code> (field 6) adds a notification badge (<code>NotificationOverlay</code>). gurotopia sends <code>add_button|name|text|noflags|0|0|</code>.</td></tr><tr><td><code>add_iap_button</code></td><td>5</td><td>four strings</td><td>An in-app purchase button (<code>_button_iap_…</code>).</td></tr><tr><td><code>add_adwatch_button</code></td><td>3</td><td>three strings</td><td>A &quot;watch an ad&quot; button. Its error message says <code>add_custom_button</code>.</td></tr><tr><td><code>add_inner_image_label_button</code></td><td>4</td><td>name, label, string, float, int, int, int, [opts]</td><td></td></tr><tr><td><code>add_friend_image_label_button</code></td><td>10</td><td>name, label, …, int, int, int, string, string, [opts]</td><td>Uses <code>game/tiles_page14.rttex</code>.</td></tr><tr><td><code>add_small_font_button</code></td><td>4</td><td>name, label, flags, [opts]</td><td></td></tr><tr><td><code>add_cmmnty_toptoday_bttn</code>, <code>add_cmmnty_toptotal_bttn</code>, <code>add_cmmnty_toprated_bttn</code></td><td>6</td><td>name, label, three strings, [opts]</td><td>Community hub buttons.</td></tr><tr><td><code>add_url_button</code></td><td>6</td><td>name, label, flags, url, url prompt, [opts]</td><td>Clicking it asks &quot;Launch&quot; / &quot;Cancel&quot;, then opens the url, instead of sending <code>dialog_return</code>. A url of <code>OPENWORLD</code>, <code>OPENSTORE</code>, <code>OPENSURVEY</code> or <code>OPENCOMMUNITY</code> does that action instead. <code>OPENSURVEY</code> sends <code>action|survey</code>.</td></tr><tr><td><code>add_image_button</code></td><td>6</td><td>name, image, three strings, [float / opts]</td><td>Layout keyword <code>imageslayout</code>.</td></tr><tr><td><code>add_embedded_url_button</code></td><td>6</td><td>like <code>add_url_button</code></td><td>Also sets <code>embedded_url = 1</code> on the button, so the url probably opens inside the game.</td></tr><tr><td><code>add_button_with_icon</code></td><td>6</td><td>name, label, frame, item id, text, [notify], [opts]</td><td>An item tile. frame is for example <code>staticBlueFrame</code>, <code>staticGreyFrame</code> or <code>staticPurpleFrame</code>. A label of <code>END_LIST</code> or <code>END_ROW</code> ends the list or the row of tiles.</td></tr><tr><td><code>add_custom_button</code></td><td>2</td><td>name, settings</td><td>A button styled by <code>key:value;…</code> keys: <code>textLabel</code>, <code>middle_colour</code>, <code>border_colour</code>, <code>alignment</code>, <code>iconAlignment</code>, <code>margin_rself</code>, <code>urlPrompt</code>, <code>link_to_rating_item</code>.</td></tr></tbody></table><h2 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Min</th><th>Fields</th><th>Sends back</th></tr></thead><tbody><tr><td><code>add_checkicon</code></td><td>7</td><td>name, label, frame, item id, text, checked (<code>1</code>), [opts]</td><td><code>&lt;name&gt;|0</code> or <code>&lt;name&gt;|1</code>. <code>min_checks</code> and <code>max_checks</code> limit how many can be ticked.</td></tr><tr><td><code>add_checkbox</code></td><td>3</td><td>name, label, state, [<code>useLabel</code>], [opts]</td><td><code>&lt;name&gt;|0</code> or <code>&lt;name&gt;|1</code>. The parser compares the state with <code>0</code>; <code>1</code> starts ticked.</td></tr><tr><td><code>dud_checkbox</code></td><td>3</td><td>same as <code>add_checkbox</code></td><td>Nothing; a checkbox drawn for show.</td></tr><tr><td><code>add_text_input</code></td><td>5</td><td>name, label, default text, max length, [opts]</td><td><code>&lt;name&gt;|&lt;text&gt;</code>.</td></tr><tr><td><code>add_text_box_input</code></td><td>6</td><td>name, (unused), default text, max length, lines (probably), [opts]</td><td><code>&lt;name&gt;|&lt;text&gt;</code>, multi-line. Line breaks are sent as <code>&lt;CR&gt;</code>.</td></tr><tr><td><code>add_text_input_password</code></td><td>5</td><td>name, label, default text, max length, (unused), [opts]</td><td><code>&lt;name&gt;|&lt;text&gt;</code>, typed hidden.</td></tr></tbody></table><p>The first text input in a dialog gets the keyboard focus.</p><h2 id="dialog-level-commands" tabindex="-1">Dialog-level commands <a class="header-anchor" href="#dialog-level-commands" aria-label="Permalink to &quot;Dialog-level commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Fields</th><th>Effect</th></tr></thead><tbody><tr><td><code>embed_data</code></td><td>key, value, …</td><td>Not drawn. Every field is appended to the dialog&#39;s hidden data followed by <code>|</code>, and the line ends with a newline, so <code>embed_data|itemID|2</code> comes back as <code>itemID|2|</code>.</td></tr><tr><td><code>end_dialog</code></td><td>name, cancel label, OK label</td><td>Sets the dialog name (<code>returnName</code>) and adds the buttons. An empty label leaves its button out. Fewer than 4 fields logs <code>Error with end_dialog parms</code>. It also sets <code>labelXMult</code> to 1.5 if nothing set it before.</td></tr><tr><td><code>add_spacer</code></td><td><code>small</code> or <code>big</code></td><td>Vertical space.</td></tr><tr><td><code>add_layout_spacer</code></td><td>layout</td><td>Spacing for a layout such as <code>imageslayout</code>.</td></tr><tr><td><code>disable_resize</code></td><td>–</td><td>Keeps the panel from resizing to its content (probably).</td></tr><tr><td><code>set_default_color</code></td><td>color code, for example <code>\`o</code></td><td>Put in front of every later text field.</td></tr><tr><td><code>set_border_color</code></td><td><code>r,g,b,a</code></td><td>The panel border color. With fewer than 4 numbers it is left as it was.</td></tr><tr><td><code>set_bg_color</code></td><td><code>r,g,b,a</code></td><td>The panel background color.</td></tr><tr><td><code>set_survey_enabled</code></td><td><code>0</code> or <code>1</code></td><td>Shows the survey button (<code>_button_survey</code>, <code>has_survey</code>).</td></tr><tr><td><code>max_checks</code>, <code>min_checks</code></td><td>number</td><td>Limits for <code>add_checkicon</code>.</td></tr><tr><td><code>add_quick_exit</code></td><td>–</td><td>An X button (<code>interface/cross.rttex</code>) in the corner. It closes the dialog without sending anything.</td></tr><tr><td><code>set_labelXMult</code></td><td>float (default 1.5)</td><td>Label width multiplier.</td></tr><tr><td><code>add_custom_label</code></td><td>text, settings</td><td>A free-placed label (<code>alignment</code> key).</td></tr><tr><td><code>add_entity_animation</code></td><td>settings</td><td>Animation keys: <code>ic_animation</code>, <code>startDelay</code>, <code>interpolationType</code> (e.g. <code>INTERPOLATE_LINEAR</code>), <code>finishType</code> (e.g. <code>ON_FINISH_DIE</code>), <code>set_value_on_finish</code>.</td></tr><tr><td><code>add_custom_image</code></td><td>settings</td><td>A free-placed image.</td></tr><tr><td><code>add_custom_break</code></td><td>–</td><td>Starts a new row below the tallest item of the current row.</td></tr><tr><td><code>add_custom_margin</code></td><td><code>x:&lt;n&gt;;y:&lt;n&gt;</code></td><td>Moves the placement point.</td></tr><tr><td><code>set_custom_spacing</code></td><td><code>x:&lt;n&gt;;y:&lt;n&gt;</code></td><td>Spacing between custom items.</td></tr><tr><td><code>set_custom_start</code></td><td><code>x:&lt;n&gt;</code></td><td>The x that rows start at.</td></tr><tr><td><code>start_custom_tabs</code>, <code>end_custom_tabs</code></td><td>–</td><td>Puts the next elements in a <code>DialogTabs</code> container, and leaves it.</td></tr><tr><td><code>add_custom_spacer</code></td><td><code>x:&lt;n&gt;;y:&lt;n&gt;</code></td><td>Moves the placement point by a multiple of the last item&#39;s size.</td></tr><tr><td><code>add_popup_name</code></td><td>name</td><td>Stored as the dialog&#39;s <code>PopupName</code>.</td></tr><tr><td><code>reset_placement_x</code></td><td>–</td><td>Probably moves the placement point back to the row start.</td></tr></tbody></table><h2 id="what-the-client-sends-back" tabindex="-1">What the client sends back <a class="header-anchor" href="#what-the-client-sends-back" aria-label="Permalink to &quot;What the client sends back&quot;">​</a></h2><p>When a button closes the dialog (<code>0x1693460</code>), the client builds the answer (<code>0x169000c</code>) and sends it as a text message (type 2):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>action|dialog_return</span></span>
<span class="line"><span>dialog_name|&lt;end_dialog name&gt;</span></span>
<span class="line"><span>&lt;embed_data lines&gt;</span></span>
<span class="line"><span>buttonClicked|&lt;button name&gt;        &lt;- only for a button made by an element</span></span>
<span class="line"><span>&lt;one line per input, in the order they were added&gt;</span></span></code></pre></div><ul><li><strong>Buttons from elements</strong> (<code>_button_&lt;name&gt;</code>) add <code>buttonClicked|&lt;name&gt;</code>, or <code>buttonClicked|&lt;name&gt;|params_…</code> when the button has <code>params</code>. A button that has a <code>url</code> doesn&#39;t send anything.</li><li><strong>The end_dialog OK button</strong> sends the answer without a <code>buttonClicked</code> line. The client adds <code>buttonClicked|button_ok</code> only for a few built-in dialog names: <code>check_ring</code>, <code>crime_edit</code>, <code>give_ring</code>, <code>prezgob</code>, <code>surgery</code>, <code>mpsuperhero</code> and <code>dialog_growpedia</code>.</li><li><strong>The end_dialog Cancel button</strong> just closes the dialog. Only <code>give_ring</code>, <code>check_ring</code> and <code>mpsuperhero</code> send an answer on cancel, with <code>buttonClicked|button_cancel</code>.</li><li><strong><code>add_quick_exit</code></strong> closes the dialog without an answer.</li><li><strong>Inputs</strong>, one line each: <ul><li>text inputs: <code>name|text</code>, with <code>|</code> in the text replaced by <code>[</code>;</li><li>multi-line inputs: the same, with line breaks sent as <code>&lt;CR&gt;</code>;</li><li>checkboxes and checkicons: <code>name|0</code> or <code>name|1</code>;</li><li>ratings: <code>rating_item|name|value</code>;</li><li>the captcha slider: <code>captcha_answer|&lt;value&gt;|CaptchaID|&lt;id&gt;</code>.</li></ul></li><li><strong>The chat filter.</strong> When the client&#39;s local chat filter is on and a text input trips it, the client adds <code>\\n|[FT##]|1</code> to the end of the message.</li><li><strong>Double clicks.</strong> A second button press in the same tick is ignored. The client logs &quot;You seem clicked buttons twice in a tick…&quot;.</li></ul>`,23)])])}const b=e(c,[["render",n]]);export{u as __pageData,b as default};
